//! Verse of the day for the menu bar: which verse to show on which day.
//!
//! The verses are compiled in (about 47 KB of text, see
//! `scripts/biblia/extraer_versiculos.py`): no database, no file reads, no
//! network. Picking one is an index into a static table.

/// Generated by `scripts/biblia/extraer_versiculos.py` from the NVI.
const DATA: &str = include_str!("versiculos_nvi.tsv");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Verse {
    /// Book, chapter and verse, as "Isaías 41:10".
    pub reference: &'static str,
    pub text: &'static str,
}

fn verses() -> impl Iterator<Item = Verse> {
    DATA.lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| {
            let (reference, text) = line.split_once('\t')?;
            Some(Verse { reference, text })
        })
}

/// How many verses there are; they repeat after this many days.
pub fn count() -> usize {
    verses().count()
}

/// The verse for a day. `day` is any running day number (days since some
/// fixed date, in local time), so consecutive days get consecutive verses
/// and the whole list is shown before any verse repeats.
pub fn of_day(day: i64) -> Verse {
    let count = count().max(1);
    let index = day.rem_euclid(count as i64) as usize;
    verses().nth(index).unwrap_or(Verse {
        reference: "Filipenses 4:13",
        text: "Todo lo puedo en Cristo que me fortalece.",
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_verse_is_clean_and_there_is_one_for_each_day_of_the_year() {
        assert_eq!(count(), 366);
        for verse in verses() {
            assert!(!verse.reference.is_empty() && !verse.text.is_empty());
            assert!(
                verse.reference.rsplit_once(' ').is_some_and(|(_, place)| {
                    place.contains(':')
                        && place
                            .chars()
                            .all(|c| c.is_ascii_digit() || ":-".contains(c))
                }),
                "{}",
                verse.reference
            );
            assert!(
                !verse.text.contains(['<', '>', '\t']),
                "{}",
                verse.reference
            );
            assert!(verse.text.chars().count() <= 240, "{}", verse.reference);
        }
    }

    #[test]
    fn consecutive_days_get_consecutive_verses_and_the_list_wraps() {
        let n = count() as i64;
        assert_ne!(of_day(0), of_day(1));
        assert_eq!(of_day(5), of_day(5 + n));
        assert_eq!(of_day(-1), of_day(n - 1));
        let distinct: std::collections::HashSet<_> =
            (0..n).map(|day| of_day(day).reference).collect();
        assert_eq!(distinct.len() as i64, n);
    }
}
